#include "platform/window.h"
#include <stdexcept>
namespace nuc {Window::Window(int w,int h,const std::string& title,bool vsync):w_(w),hgt_(h){if(!glfwInit())throw std::runtime_error("GLFW init failed");glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR,3);glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR,3);glfwWindowHint(GLFW_OPENGL_PROFILE,GLFW_OPENGL_CORE_PROFILE);glfwWindowHint(GLFW_OPENGL_DEBUG_CONTEXT,GLFW_TRUE);h_=glfwCreateWindow(w,h,title.c_str(),nullptr,nullptr);if(!h_){glfwTerminate();throw std::runtime_error("GLFW window creation failed");}glfwMakeContextCurrent(h_);glfwSwapInterval(vsync?1:0);glfwSetWindowUserPointer(h_,this);glfwSetFramebufferSizeCallback(h_,resized);glViewport(0,0,w,h);}Window::~Window(){if(h_)glfwDestroyWindow(h_);glfwTerminate();}void Window::resized(GLFWwindow* h,int w,int z){auto* self=static_cast<Window*>(glfwGetWindowUserPointer(h));self->w_=w;self->hgt_=z;glViewport(0,0,w,z);}bool Window::should_close()const{return glfwWindowShouldClose(h_)!=0;}void Window::poll(){glfwPollEvents();}void Window::swap(){glfwSwapBuffers(h_);}void Window::close(){glfwSetWindowShouldClose(h_,GLFW_TRUE);}}
